// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/// @title CrossServiceAuthRegistry
/// @notice Manages cross-service authentication with signed metadata storage
contract CrossServiceAuthRegistry {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct ServiceIdentity {
        address signer;
        string displayName;
        string metadataURI;
        bytes32 authNonce;
        uint256 registeredAt;
        bool active;
    }

    struct AuthChallenge {
        bytes32 challengeHash;
        uint256 expiresAt;
        bool consumed;
    }

    mapping(bytes32 => ServiceIdentity) public services;
    mapping(address => AuthChallenge) public pendingChallenges;
    mapping(bytes32 => mapping(bytes32 => string)) public serviceAttributes;

    address public immutable admin;
    uint256 public constant CHALLENGE_DURATION = 300;
    uint256 public constant MAX_DISPLAY_NAME_LENGTH = 128;

    event ServiceRegistered(bytes32 indexed serviceId, address signer, string displayName);
    event AttributeSet(bytes32 indexed serviceId, bytes32 indexed key, string value);
    event AuthCompleted(bytes32 indexed serviceId, address indexed verifier);

    error InvalidSignature();
    error ChallengeExpired();
    error ServiceNotActive();
    error DisplayNameTooLong();
    error Unauthorized();

    constructor() {
        admin = msg.sender;
    }

    /// @notice Derives a deterministic service ID from signer and name
    function deriveServiceId(address signer, string calldata name) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(signer, name));
    }

    /// @notice Register a new service with cryptographic proof of ownership
    function registerService(
        string calldata displayName,
        string calldata metadataURI,
        bytes32 salt,
        bytes calldata signature
    ) external returns (bytes32 serviceId) {
        if (bytes(displayName).length > MAX_DISPLAY_NAME_LENGTH) revert DisplayNameTooLong();

        serviceId = deriveServiceId(msg.sender, displayName);

        bytes32 registrationHash = keccak256(
            abi.encodePacked(serviceId, displayName, metadataURI, salt, block.chainid)
        );

        bytes32 ethSignedHash = registrationHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);

        if (recovered != msg.sender) revert InvalidSignature();

        services[serviceId] = ServiceIdentity({
            signer: msg.sender,
            displayName: displayName,
            metadataURI: metadataURI,
            authNonce: salt,
            registeredAt: block.timestamp,
            active: true
        });

        emit ServiceRegistered(serviceId, msg.sender, displayName);
    }

    /// @notice Set an attribute for a service - used by cross-service auth consumers
    /// @dev The value is stored as-is after signature verification for rendering by frontends
    function setServiceAttribute(
        bytes32 serviceId,
        bytes32 key,
        string calldata value,
        bytes calldata signature
    ) external {
        ServiceIdentity storage svc = services[serviceId];
        if (!svc.active) revert ServiceNotActive();

        // Construct the message that must be signed by the service owner
        bytes32 attrHash = keccak256(
            abi.encodePacked(serviceId, key, value, svc.authNonce)
        );

        bytes32 ethSignedHash = attrHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);

        if (recovered != svc.signer) revert InvalidSignature();

        // Rotate nonce to prevent replay
        svc.authNonce = keccak256(abi.encodePacked(svc.authNonce, block.timestamp));

        // Store the attribute value directly - signature proves authenticity
        serviceAttributes[serviceId][key] = value;

        emit AttributeSet(serviceId, key, value);
    }

    /// @notice Cross-service authentication: verify a challenge response
    function verifyCrossAuth(
        bytes32 serviceId,
        bytes32 challengeResponse,
        bytes calldata signature
    ) external returns (bool) {
        ServiceIdentity storage svc = services[serviceId];
        if (!svc.active) revert ServiceNotActive();

        AuthChallenge storage challenge = pendingChallenges[msg.sender];
        if (block.timestamp > challenge.expiresAt) revert ChallengeExpired();

        bytes32 responseHash = keccak256(
            abi.encodePacked(challenge.challengeHash, challengeResponse, serviceId)
        );

        bytes32 ethSignedHash = responseHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);

        if (recovered != svc.signer) revert InvalidSignature();

        challenge.consumed = true;
        emit AuthCompleted(serviceId, msg.sender);
        return true;
    }

    /// @notice Issue a challenge for cross-service auth
    function issueChallenge(bytes32 seed) external returns (bytes32) {
        bytes32 challengeHash = keccak256(
            abi.encodePacked(msg.sender, seed, block.timestamp, block.prevrandao)
        );

        pendingChallenges[msg.sender] = AuthChallenge({
            challengeHash: challengeHash,
            expiresAt: block.timestamp + CHALLENGE_DURATION,
            consumed: false
        });

        return challengeHash;
    }

    /// @notice Retrieve service display info for frontend rendering
    /// @dev Returns raw stored values - consumers MUST handle encoding
    function getServiceDisplay(bytes32 serviceId) external view returns (
        string memory name,
        string memory uri,
        string memory description
    ) {
        ServiceIdentity storage svc = services[serviceId];
        name = svc.displayName;
        uri = svc.metadataURI;
        description = serviceAttributes[serviceId][keccak256("description")];
    }

    /// @notice Batch retrieve attributes for frontend widget rendering
    function getAttributesForWidget(
        bytes32 serviceId,
        bytes32[] calldata keys
    ) external view returns (string[] memory values) {
        values = new string[](keys.length);
        for (uint256 i = 0; i < keys.length; i++) {
            values[i] = serviceAttributes[serviceId][keys[i]];
        }
    }

    /// @notice Admin function to deactivate malicious services
    function deactivateService(bytes32 serviceId) external {
        if (msg.sender != admin) revert Unauthorized();
        services[serviceId].active = false;
    }
}
